import { z } from 'zod/v3';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import type { CallToolResult } from '@modelcontextprotocol/sdk/types.js';
import type { RequestHandlerExtra } from '@modelcontextprotocol/sdk/shared/protocol.js';
import type {
  ServerRequest,
  ServerNotification,
} from '@modelcontextprotocol/sdk/types.js';
import { errorResult, type CliEnvelope } from '../cli/envelope';
import { commandErrorResult } from '../cli/commands/shared';

export interface IntentToolDependencies {
  mcp: McpServer;
  runCommand: (
    command: string,
    rest: string[],
    options?: { handoffArgs?: string[]; signal?: AbortSignal },
  ) => Promise<IntentResult>;
  projectArgs: (project?: string) => string[];
  completeToolCall: (input: {
    toolName: string;
    startedAt: number;
    envelope: CliEnvelope;
    progress?: string[];
    sessionId?: string;
  }) => CallToolResult;
  serveProject?: string;
  callerAgent?: string;
}
export interface IntentResult {
  envelope: CliEnvelope;
  progress?: string[];
}
export type IntentExtra = RequestHandlerExtra<
  ServerRequest,
  ServerNotification
>;
export const requiredText = z.string().trim().min(1);
export const localRead = {
  readOnlyHint: true,
  destructiveHint: false,
  openWorldHint: false,
  idempotentHint: true,
};
export const localChange = {
  readOnlyHint: false,
  destructiveHint: true,
  openWorldHint: false,
};
export const externalChange = {
  readOnlyHint: false,
  destructiveHint: true,
  openWorldHint: true,
};

export const registerIntentTool = <Shape extends z.ZodRawShape>(
  dependencies: IntentToolDependencies,
  definition: {
    name: string;
    title: string;
    description: string;
    shape: Shape;
    annotations: {
      readOnlyHint: boolean;
      destructiveHint: boolean;
      openWorldHint: boolean;
      idempotentHint?: boolean;
    };
  },
  handle: (
    input: z.infer<z.ZodObject<Shape>>,
    extra: IntentExtra,
  ) => Promise<IntentResult>,
): void => {
  dependencies.mcp.registerTool(
    definition.name,
    {
      title: definition.title,
      description: definition.description,
      annotations: definition.annotations,
      inputSchema: z.object(definition.shape).strict(),
    },
    async (input, extra) => {
      const startedAt = Date.now();
      let result: IntentResult;
      try {
        result = await handle(input, extra);
      } catch (error) {
        result = {
          envelope: commandErrorResult(definition.name, error).envelope,
        };
      }
      return dependencies.completeToolCall({
        toolName: definition.name,
        startedAt,
        ...result,
      });
    },
  );
};

export const invalidIntent = (name: string, message: string): IntentResult => ({
  envelope: errorResult(name, 'USAGE_ERROR', message).envelope,
});
export const optionArgs = (flag: string, value: unknown): string[] =>
  value === undefined
    ? []
    : [flag, typeof value === 'string' ? value : JSON.stringify(value)];
